"""
Phase4StatisticalValidation.py
================================

Phase 4 - Statistical validation of DRO superiority + invoke Interpretation.

OUTPUTS (all prefixed with `{City}_{YearMonthRange}{RunSuffix}_`)
  * statistical_summary.csv
  * comparative_validation.csv
  * scale_invariance_summary.csv
  * per_cluster_means.csv
  * interpretation.txt   (auto-generated by Interpretation.py)
  * interpretation.tex    (auto-generated by Interpretation.py)
"""

# Import the scipy stats module for statistical hypothesis testing.
import scipy.stats as stats
# Import the numpy library for numerical array operations.
import numpy as np
# Import the pandas library for tabular result storage.
import pandas as pd
# Import the os library for file path construction.
import os
# Import the shared configuration module for global knobs and paths.
import Config
# Import the interpretation utility for auto-generated report writing.
import Interpretation


def ComputeWilcoxonValidation(baselineCostArray, proposedCostArray):
  """Compute the Wilcoxon signed-rank test and the effect size."""
  # Compute the paired differences for the diagnostic.
  pairedDifferences = np.array(baselineCostArray) - np.array(proposedCostArray)
  # Count the number of non-zero paired differences.
  nonZeroCount = int(np.sum(pairedDifferences != 0))
  # Fall back to a degenerate result when all differences are zero.
  if (nonZeroCount == 0):
    # Return a non-significant sentinel result.
    return 1.0, 0.0, 0.0
  # Perform the Wilcoxon signed-rank test on the paired cost samples.
  testStatistic, pValue = stats.wilcoxon(baselineCostArray, proposedCostArray, alternative="greater")
  # Use the count of non-zero paired differences as the sample size.
  sampleSize = nonZeroCount
  # Compute the standardized mean of the test statistic under the null.
  meanStatistic = sampleSize * (sampleSize + 1) / 4.0
  # Compute the variance of the test statistic under the null hypothesis.
  varianceStatistic = sampleSize * (sampleSize + 1) * (2 * sampleSize + 1) / 24.0
  # Guard against a zero variance.
  if (varianceStatistic <= 0):
    # Return a non-significant sentinel result.
    return float(pValue), 0.0, float(testStatistic)
  # Compute the Z score using the normal approximation.
  zScore = (testStatistic - meanStatistic) / np.sqrt(varianceStatistic)
  # Calculate the Cohen effect size r using the absolute Z score.
  effectSize = abs(zScore) / np.sqrt(sampleSize)
  # Return the p-value, the effect size, and the test statistic.
  return float(pValue), float(effectSize), float(zScore)


def ComputeBootstrapMeanConfidenceInterval(sampleArray, resampleCount, confidenceLevel, randomGenerator):
  """Compute a bootstrap confidence interval for the mean."""
  # Convert the sample array to a numpy array.
  sampleArray = np.asarray(sampleArray, dtype=float)
  # Initialize the list storing bootstrap mean replicates.
  bootstrapMeans = []
  # Iterate over each bootstrap resample index.
  for resampleIndex in range(resampleCount):
    # Draw a bootstrap sample with replacement.
    bootstrapSample = randomGenerator.choice(sampleArray, size=len(sampleArray), replace=True)
    # Append the bootstrap sample mean to the list.
    bootstrapMeans.append(float(np.mean(bootstrapSample)))
  # Compute the lower percentile bound from the bootstrap distribution.
  lowerBound = float(np.percentile(bootstrapMeans, 100.0 * (1.0 - confidenceLevel) / 2.0))
  # Compute the upper percentile bound from the bootstrap distribution.
  upperBound = float(np.percentile(bootstrapMeans, 100.0 * (1.0 + confidenceLevel) / 2.0))
  # Return the lower and upper confidence bounds.
  return lowerBound, upperBound


def CategorizeScaleBand(clusterSize):
  """Categorize a cluster size into a Small / Medium / Large scale band."""
  # Return the small band label when the cluster size is at most twenty.
  if (clusterSize <= 20):
    # Return the small band label.
    return "Small"
  # Return the medium band label when the cluster size is at most forty.
  if (clusterSize <= 40):
    # Return the medium band label.
    return "Medium"
  # Return the large band label for all remaining cluster sizes.
  return "Large"


def main():
  """Main entry point: compute statistics and write interpretation files."""
  # Instantiate a fresh random generator for bootstrap resampling.
  randomGenerator = np.random.default_rng(Config.GLOBAL_RANDOM_SEED + 31)
  # Load the out-of-sample costs from the tagged CSV file.
  outOfSampleDataFrame = pd.read_csv(Config.TaggedFileName("outofsample_costs.csv"))
  # Retrieve the experiment configuration dictionary.
  configuration = Config.EXPERIMENT_CONFIGURATION
  # Pivot the out-of-sample costs to pair methods on the same scenario.
  pivotFrame = outOfSampleDataFrame.pivot(
    index=["ClusterId", "ScenarioIndex"], columns="Method", values="TotalCost").reset_index()
  # Build the cluster size map for the pivoted frame.
  clusterSizeMap = outOfSampleDataFrame[["ClusterId", "ClusterSize"]].drop_duplicates().set_index("ClusterId")[
    "ClusterSize"].to_dict()
  # Assign the cluster size column to the pivoted frame.
  pivotFrame["ClusterSize"] = pivotFrame["ClusterId"].map(clusterSizeMap)
  # Assign the scale band label to the pivoted frame.
  pivotFrame["ScaleBand"] = pivotFrame["ClusterSize"].apply(CategorizeScaleBand)
  # Extract the per-method cost arrays.
  droCostArray = pivotFrame["DRO"].to_numpy()
  evCostArray = pivotFrame["EV"].to_numpy()
  saaCostArray = pivotFrame["SAA"].to_numpy()
  # Compute the Wilcoxon validation for the DRO versus EV comparison.
  evPValue, evEffectSize, evZScore = ComputeWilcoxonValidation(evCostArray, droCostArray)
  # Compute the Wilcoxon validation for the DRO versus SAA comparison.
  saaPValue, saaEffectSize, saaZScore = ComputeWilcoxonValidation(saaCostArray, droCostArray)
  # Compute the mean cost reduction percentage for DRO versus EV.
  evMeanReduction = float(np.mean(evCostArray - droCostArray) / np.mean(evCostArray) * 100.0)
  # Compute the mean cost reduction percentage for DRO versus SAA.
  saaMeanReduction = float(np.mean(saaCostArray - droCostArray) / np.mean(saaCostArray) * 100.0)
  # Compute the bootstrap confidence interval for the mean DRO cost.
  droMeanLower, droMeanUpper = ComputeBootstrapMeanConfidenceInterval(
    droCostArray, configuration["BootstrapResamples"],
    configuration["BootstrapConfidence"], randomGenerator)
  # Compute the bootstrap confidence interval for the mean EV cost.
  evMeanLower, evMeanUpper = ComputeBootstrapMeanConfidenceInterval(
    evCostArray, configuration["BootstrapResamples"],
    configuration["BootstrapConfidence"], randomGenerator)
  # Compute the bootstrap confidence interval for the mean SAA cost.
  saaMeanLower, saaMeanUpper = ComputeBootstrapMeanConfidenceInterval(
    saaCostArray, configuration["BootstrapResamples"],
    configuration["BootstrapConfidence"], randomGenerator)
  # Initialize the list storing the overall statistical summary records.
  summaryRecords = []
  # Append the DRO summary record.
  summaryRecords.append({"Method"    : "DRO", "MeanCost": float(np.mean(droCostArray)),
                         "StdCost"   : float(np.std(droCostArray, ddof=1)),
                         "MedianCost": float(np.median(droCostArray)),
                         "Ci95Lower" : droMeanLower, "Ci95Upper": droMeanUpper})
  # Append the EV summary record.
  summaryRecords.append({"Method"    : "EV", "MeanCost": float(np.mean(evCostArray)),
                         "StdCost"   : float(np.std(evCostArray, ddof=1)),
                         "MedianCost": float(np.median(evCostArray)),
                         "Ci95Lower" : evMeanLower, "Ci95Upper": evMeanUpper})
  # Append the SAA summary record.
  summaryRecords.append({"Method"    : "SAA", "MeanCost": float(np.mean(saaCostArray)),
                         "StdCost"   : float(np.std(saaCostArray, ddof=1)),
                         "MedianCost": float(np.median(saaCostArray)),
                         "Ci95Lower" : saaMeanLower, "Ci95Upper": saaMeanUpper})
  # Convert the summary records to a pandas dataframe.
  summaryDataFrame = pd.DataFrame(summaryRecords)
  # Save the overall statistical summary to a tagged CSV file.
  summaryDataFrame.to_csv(Config.TaggedFileName("statistical_summary.csv"), index=False)
  # Build the comparative validation record.
  comparativeRecords = [
    {"Comparison"    : "DRO_vs_EV", "MeanReductionPercent": evMeanReduction,
     "WilcoxonPValue": evPValue, "CohenR": evEffectSize, "ZScore": evZScore,
     "SampleSize"    : int(len(droCostArray))},
    {"Comparison"    : "DRO_vs_SAA", "MeanReductionPercent": saaMeanReduction,
     "WilcoxonPValue": saaPValue, "CohenR": saaEffectSize, "ZScore": saaZScore,
     "SampleSize"    : int(len(droCostArray))}]
  # Convert the comparative records to a pandas dataframe.
  comparativeDataFrame = pd.DataFrame(comparativeRecords)
  # Save the comparative validation to a tagged CSV file.
  comparativeDataFrame.to_csv(Config.TaggedFileName("comparative_validation.csv"), index=False)
  # Melt the pivoted frame back to long form for the scale-invariance analysis.
  longFormFrame = pivotFrame.melt(
    id_vars=["ClusterId", "ClusterSize", "ScaleBand"],
    value_vars=["EV", "SAA", "DRO"], var_name="Method", value_name="TotalCost")
  # Compute the scale-invariance summary grouped by band and method.
  scaleInvarianceFrame = longFormFrame.groupby(["ScaleBand", "Method"])["TotalCost"].agg(
    ["mean", "std", "count"]).round(2).reset_index()
  # Save the scale-invariance summary to a tagged CSV file.
  scaleInvarianceFrame.to_csv(Config.TaggedFileName("scale_invariance_summary.csv"), index=False)
  # Compute the per-cluster mean cost per method for the visualization phase.
  perClusterFrame = longFormFrame.groupby(["ClusterId", "ClusterSize", "ScaleBand", "Method"])[
    "TotalCost"].mean().reset_index()
  # Save the per-cluster mean costs to a tagged CSV file.
  perClusterFrame.to_csv(Config.TaggedFileName("per_cluster_means.csv"), index=False)
  # Print the comparative validation results.
  print("Phase 4 comparative validation [%s]:" % Config.RUN_TAG)
  # Print the comparative dataframe to the console.
  print(comparativeDataFrame.to_string(index=False))
  # Print the scale-invariance summary header.
  print("Phase 4 scale-invariance summary [%s]:" % Config.RUN_TAG)
  # Print the scale-invariance dataframe to the console.
  print(scaleInvarianceFrame.to_string(index=False))
  # Invoke the interpretation utility to write .txt and .tex reports.
  Interpretation.GenerateSingleRunInterpretation(
    runTag=Config.RUN_TAG,
    summaryDataFrame=summaryDataFrame,
    comparativeDataFrame=comparativeDataFrame,
    scaleInvarianceFrame=scaleInvarianceFrame,
    configuration=configuration)
  # Print a confirmation message for the interpretation files.
  print("Phase 4 complete [%s]: wrote statistical_summary.csv, comparative_validation.csv, "
        "scale_invariance_summary.csv, per_cluster_means.csv, interpretation.txt, interpretation.tex." % (
          Config.RUN_TAG))


# Execute the main function when the script runs as the entry point.
if __name__ == "__main__":
  # Invoke the main entry point.
  main()
